import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        String s = r.next(), kit = r.next();
        long balance = 0, minimum = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == '(' ? 1 : -1;
            minimum = Math.min(minimum, balance);
        }
        long left = -minimum, right = left + balance;
        int k = kit.length(), no = 0, nc = 0;
        long[] opens = new long[k], closes = new long[k];
        for (int i = 0; i < k; i++) {
            long v = r.nextLong();
            if (kit.charAt(i) == '(') opens[no++] = v; else closes[nc++] = v;
        }
        opens = Arrays.copyOf(opens, no);
        closes = Arrays.copyOf(closes, nc);
        Arrays.sort(opens);
        Arrays.sort(closes);
        // Walk both arrays from the largest score down.
        int L = (int) Math.min(left, no), R = (int) Math.min(right, nc);
        long ans = 0;
        for (int i = 0; i < L; i++) ans += opens[no - 1 - i];
        for (int i = 0; i < R; i++) ans += closes[nc - 1 - i];
        for (int i = L, j = R; i < no && j < nc; i++, j++) ans += Math.max(0, opens[no - 1 - i] + closes[nc - 1 - j]);
        System.out.println(ans);
    }
}

final class FastReader {
    private final java.io.InputStream in = System.in;
    private final byte[] buf = new byte[1 << 16];
    private int len = 0, ptr = 0;

    private int read() throws java.io.IOException {
        if (ptr == len) {
            len = in.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) { len = 0; return -1; }
        }
        return buf[ptr++];
    }

    String next() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = read(); }
        return sb.toString();
    }

    long nextLong() throws java.io.IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = read(); }
        return neg ? -r : r;
    }

    int nextInt() throws java.io.IOException { return (int) nextLong(); }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"slices"
)

func main() {
	s, kit := readToken(), readToken()
	balance, minimum := 0, 0
	for i := 0; i < len(s); i++ {
		if s[i] == '(' {
			balance++
		} else {
			balance--
		}
		minimum = min(minimum, balance)
	}
	left := -minimum
	right := left + balance
	var opens, closes []int
	for i := 0; i < len(kit); i++ {
		v := readInt()
		if kit[i] == '(' {
			opens = append(opens, v)
		} else {
			closes = append(closes, v)
		}
	}
	// Sort descending.
	slices.Sort(opens)
	slices.Reverse(opens)
	slices.Sort(closes)
	slices.Reverse(closes)
	L, R := min(left, len(opens)), min(right, len(closes))
	ans := 0
	for i := 0; i < L; i++ {
		ans += opens[i]
	}
	for i := 0; i < R; i++ {
		ans += closes[i]
	}
	for i, j := L, R; i < len(opens) && j < len(closes); i, j = i+1, j+1 {
		ans += max(0, opens[i]+closes[j])
	}
	fmt.Println(ans)
}

var reader = bufio.NewReaderSize(os.Stdin, 1<<16)

func readToken() string {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	var buf []byte
	for err == nil && b > ' ' {
		buf = append(buf, b)
		b, err = reader.ReadByte()
	}
	return string(buf)
}

func readInt() int {
	b, err := reader.ReadByte()
	for err == nil && b <= ' ' {
		b, err = reader.ReadByte()
	}
	neg := false
	if b == '-' {
		neg = true
		b, err = reader.ReadByte()
	}
	r := 0
	for err == nil && b >= '0' && b <= '9' {
		r = r*10 + int(b-'0')
		b, err = reader.ReadByte()
	}
	if neg {
		return -r
	}
	return r
}
